#!/usr/bin/env bun
/**
 * Regenerates the embedded guionista-kit snapshot used by `bradbit init`.
 *
 * Usage:
 *   bun run script/sync-guionista-kit.ts /path/to/guionista-kit
 *
 * The generated file is committed so the CLI binary and the tests do not need
 * the kit repository at build time.
 */

import { readdir, readFile, writeFile } from "node:fs/promises"
import path from "node:path"

const source = process.argv[2]
if (!source) {
  console.error("Usage: bun run script/sync-guionista-kit.ts <path-to-guionista-kit>")
  process.exit(2)
}

const root = path.resolve(source)
const output = path.resolve(import.meta.dir, "../src/kit/guionista-kit.generated.ts")
const ignored = new Set([".git", "exports", ".DS_Store", "node_modules"])

async function walk(directory: string, prefix = ""): Promise<Array<[string, string]>> {
  const entries = await readdir(directory, { withFileTypes: true })
  const files: Array<[string, string]> = []
  for (const entry of entries.toSorted((a, b) => a.name.localeCompare(b.name))) {
    if (ignored.has(entry.name)) continue
    const relative = prefix ? `${prefix}/${entry.name}` : entry.name
    const absolute = path.join(directory, entry.name)
    if (entry.isDirectory()) {
      files.push(...(await walk(absolute, relative)))
      continue
    }
    if (!entry.isFile()) continue
    files.push([relative, await readFile(absolute, "utf8")])
  }
  return files
}

const files = await walk(root)
const lines = [
  "// Generated by packages/cli/script/sync-guionista-kit.ts. Do not edit by hand.",
  "// Source: guionista-kit (structure identical to the editor's bundled template).",
  "export const guionistaKitFiles: Record<string, string> = {",
  ...files.map(([relative, content]) => `  ${JSON.stringify(relative)}: ${JSON.stringify(content)},`),
  "}",
  "",
]
await writeFile(output, lines.join("\n"))
console.log(`Wrote ${files.length} files to ${path.relative(process.cwd(), output)}`)
